query Public {
  cdp {
    getProfile(profileID: {id: "nobody"}) {
      cdp_profileIDs {
        id
      }
    }
  }
}

query Privileged {
  cdp {
    findProfiles(first: 100) {
      edges {
        node {
          cdp_profileIDs {
            id
          }
        }
      }
    }
  }
}
